// Assemble the static corridor from inventory.json, galleryList.json and rooms/*/room.json.
// The legacy hall, portals, and original two rooms keep their settings in exhibition.json.
// node scripts/assemble-painted-worlds.mjs [inventory.json] [--allow-pending] [--check | --bundle <new-directory>]
// --check compares generated bytes. --bundle writes only the referenced assets and runtime to a new web root.
import { copyFile, mkdir, open, readFile, realpath, rename, stat, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const publicRoot = fileURLToPath(new URL('../public/', import.meta.url))
const worlds = path.join(publicRoot, 'painted-worlds')
const manifestPath = path.join(worlds, 'exhibition.json')
const registryPath = path.join(worlds, 'work-registry.json')
const args = process.argv.slice(2)
const inventoryPath = args[0] && !args[0].startsWith('--') ? args.shift() : registryPath
const options = args
const allowPending = options.includes('--allow-pending')
const check = options.includes('--check')
const bundleIndex = options.indexOf('--bundle')
const bundle = bundleIndex === -1 ? null : options[bundleIndex + 1]
const assets = new Set()
const slugPattern = /^[a-z0-9]+(?:-[a-z0-9]+)*$/
const imageExtension = /\.(?:webp|png|jpe?g|avif)$/i

function assert(valid, message) {
  if (!valid) throw new Error(message)
}

async function json(filename) {
  return JSON.parse((await readFile(filename, 'utf8')).replace(/^\uFEFF/, ''))
}

function within(directory, filename) {
  const relative = path.relative(directory, filename)
  return !!relative && relative !== '..' && !relative.startsWith('..' + path.sep) && !path.isAbsolute(relative)
}

async function asset(filename, directory = publicRoot) {
  assert(within(directory, filename), `Asset outside ${directory}: ${filename}`)
  const [root, file] = await Promise.all([realpath(directory), realpath(filename)])
  assert(within(root, file) && (await stat(file)).isFile(), `Invalid asset: ${filename}`)
  assets.add(filename)
}

function relativeURL(filename) {
  const url = path.relative(worlds, filename).split(path.sep).join('/')
  return url.startsWith('../') ? url : './' + url
}

async function roomAsset(id, url, extension) {
  const root = path.join(worlds, 'rooms', id)
  assert(typeof url === 'string' && extension.test(url) && !/[\\?#:%]/.test(url) && !url.startsWith('/'), `${id}: invalid asset path ${url}`)
  // Accept paths relative to room.json and paths already relative to exhibition.json.
  const filename = path.resolve(/^\.?\/?rooms\//.test(url) ? worlds : root, url)
  await asset(filename, root)
  return relativeURL(filename)
}

const number = (value, min, max) => Number.isFinite(value) && value >= min && value <= max
const vector = value => Array.isArray(value) && value.length === 3 && value.every(Number.isFinite)
const label = value => typeof value === 'string' && value.trim().length > 0
const color = value => (Number.isInteger(value) && number(value, 0, 0xffffff)) ||
  (typeof value === 'string' && /^#(?:[\da-f]{3}|[\da-f]{6})$/i.test(value))

async function validateGLB(id, url) {
  const file = await open(path.resolve(worlds, url), 'r')
  try {
    const header = Buffer.alloc(20)
    const { bytesRead } = await file.read(header, 0, header.length, 0)
    const chunkLength = header.readUInt32LE(12)
    const length = (await file.stat()).size
    assert(bytesRead === header.length && header.toString('ascii', 0, 4) === 'glTF' &&
      header.readUInt32LE(4) === 2 && header.readUInt32LE(8) === length &&
      chunkLength <= length - header.length && header.toString('ascii', 16, 20) === 'JSON', `${id}: invalid GLB header`)
    const chunk = Buffer.alloc(chunkLength)
    await file.read(chunk, 0, chunk.length, header.length)
    const gltf = JSON.parse(chunk.toString('utf8'))
    const references = [...(gltf.buffers ?? []), ...(gltf.images ?? [])]
    assert(references.every(({ uri }) => uri === undefined || uri.startsWith('data:')), `${id}: GLB must include its own buffers and textures`)
    const unsupported = (gltf.extensionsRequired ?? []).filter(name => name === 'KHR_draco_mesh_compression' || name === 'KHR_texture_basisu')
    assert(!unsupported.length, `${id}: renderer cannot decode ${unsupported.join(', ')}`)
  } finally {
    await file.close()
  }
}

function validateLook(id, look) {
  assert(look && typeof look === 'object' && !Array.isArray(look), `${id}: invalid look`)
  for (const key of ['sky', 'key', 'fill', 'ground']) {
    assert(look[key] === undefined || color(look[key]), `${id}: invalid look.${key}`)
  }
  for (const key of ['keyIntensity', 'fillIntensity', 'skyIntensity']) {
    assert(look[key] === undefined || number(look[key], 0, Infinity), `${id}: invalid look.${key}`)
  }
  assert(look.shadowIntensity === undefined || number(look.shadowIntensity, 0, 1), `${id}: invalid look.shadowIntensity`)
  const fog = look.fog
  if (fog != null) {
    assert(color(fog.color) && number(fog.near, 0, Infinity) && number(fog.far, 0, Infinity) && fog.near < fog.far, `${id}: invalid fog`)
  }
}

async function readRoom(entry) {
  const { id, year, workId } = entry
  const filename = path.join(worlds, 'rooms', id, 'room.json')
  let room
  try {
    room = await json(filename)
  } catch (error) {
    if (error.code === 'ENOENT') return null
    throw error
  }
  assert(room.id === id && room.year === year && room.workId === workId, `${id}: room identity differs from inventory`)
  assert(label(room.title), `${id}: missing room title`)
  const { views, stills, mobileStills, look } = room
  assert(Array.isArray(views) && views.length >= 2, `${id}: at least two views are required`)
  for (const view of views) {
    assert(label(view.label) && label(view.description) && vector(view.position) && vector(view.target) &&
      view.position.some((coordinate, index) => coordinate !== view.target[index]) &&
      number(view.fov, 1, 179) && number(view.mobileFov, 1, 179), `${id}: invalid view`)
  }
  assert(new Set(views.map(({ position, target }) => JSON.stringify([position, target]))).size === views.length, `${id}: duplicate views`)
  validateLook(id, look)
  assert([stills, mobileStills].every(list => Array.isArray(list) && list.length === views.length), `${id}: views and still counts differ`)
  const [model, desktop, mobile] = await Promise.all([
    roomAsset(id, room.model, /\.glb$/i),
    Promise.all(stills.map(url => roomAsset(id, url, imageExtension))),
    Promise.all(mobileStills.map(url => roomAsset(id, url, imageExtension)))
  ])
  await validateGLB(id, model)
  return { model, settings: { title: room.title, views, stills: desktop, mobileStills: mobile, look } }
}

function dateFromMetadata(value) {
  const [, year, month, day] = /^(\d{4}) ([A-Z][a-z]{2}) (\d{1,2})$/.exec(value) ?? []
  const monthNumber = 'Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec'.split(' ').indexOf(month) + 1
  assert(year && monthNumber && number(Number(day), 1, 31), `Invalid gallery date: ${value}`)
  return `${year}.${String(monthNumber).padStart(2, '0')}.${day.padStart(2, '0')}`
}

async function assemble() {
  assert((bundleIndex === -1 || bundle && !bundle.startsWith('--')) &&
    !(check && bundle) && options.length === Number(allowPending) + Number(check) + 2 * Number(!!bundle),
  'Usage: node scripts/assemble-painted-worlds.mjs [inventory.json] [--allow-pending] [--check | --bundle <new-directory>]')

  const [inventory, gallery, previous] = await Promise.all([
    json(inventoryPath), json(path.join(publicRoot, 'galleryList.json')), json(manifestPath)
  ])
  const byId = new Map(gallery.Img.map(work => ['digital-' + work.filename.replace(/\.[^/.]+$/, ''), work]))
  const legacyIds = Object.keys(previous.portals)
  const legacyModels = Object.fromEntries(['hall', 'statue', ...legacyIds].map(id => [id, previous.models[id]]))
  const rooms = Object.fromEntries(['hall', ...legacyIds].map(id => [id, previous.rooms[id]]))
  const models = { ...legacyModels }
  const registry = []
  const seenIds = new Set(['hall', 'statue'])
  const seenWorks = new Set()
  const pending = []
  for (const item of inventory) {
    const { year, workId } = item
    const id = item.slug ?? item.id
    assert(typeof id === 'string' && slugPattern.test(id) && !seenIds.has(id) && !seenWorks.has(workId), `Invalid or duplicate room: ${id}`)
    const work = byId.get(workId)
    assert(work && (item.filename === undefined || work.filename === item.filename) && label(work.title),
      `${id}: inventory workId and filename do not match a gallery work`)
    const date = dateFromMetadata(work.time)
    assert(year === Number(date.slice(0, 4)), `${id}: gallery date and inventory year differ`)
    seenIds.add(id)
    seenWorks.add(workId)
    const stem = work.filename.replace(/\.[^/.]+$/, '.webp')
    const art = { title: work.title, date, src: `../images/_thumbs/1600w/${stem}` }
    const thumb = `../images/_thumbs/400w/${stem}`
    await Promise.all([art.src, thumb].map(url => asset(path.resolve(worlds, url))))
    const entry = { id, workId, year, title: work.title, art: { ...art, thumb } }
    const ready = legacyIds.includes(id) ? { settings: rooms[id] } : await readRoom(entry)
    if (ready) {
      entry.title = ready.settings.title
      rooms[id] = { ...ready.settings, art }
      if (ready.model) models[id] = ready.model
    } else {
      pending.push(id)
    }
    registry.push(entry)
  }
  for (const id of legacyIds) assert(seenIds.has(id), `Legacy room missing from inventory: ${id}`)
  for (const [id, { filename }] of byId) {
    if (/^gallery\/202[456]年電繪作品\//.test(filename)) assert(seenWorks.has(id), `Gallery work missing from inventory: ${id}`)
  }
  assert(allowPending || !pending.length, `Missing room.json: ${pending.join(', ')}`)
  const years = [...new Set(registry.map(work => work.year))].sort((a, b) => a - b)
  const alternateHallStills = years.slice(0, -1).flatMap(year => [`./media/hall-${year}.webp`, `./media/hall-${year}-mobile.webp`])
  await Promise.all([
    ...Object.values(legacyModels), previous.sky, previous.canopyLight, ...Object.values(previous.reflections),
    ...[rooms.hall, ...legacyIds.map(id => rooms[id])].flatMap(room => [...room.stills, ...room.mobileStills]),
    ...alternateHallStills
  ].map(url => asset(path.resolve(worlds, url))))

  const manifest = { ...previous, models, rooms }
  const outputs = [[manifestPath, manifest], [registryPath, registry]].map(([filename, value]) => [filename, JSON.stringify(value, null, 2) + '\n'])
  if (check) {
    for (const [filename, content] of outputs) {
      const current = (await readFile(filename, 'utf8')).replace(/\r\n/g, '\n')
      assert(current === content, `Outdated ${path.basename(filename)}. Run assembly again.`)
    }
  } else if (!bundle) {
    for (const [filename, content] of outputs) {
      const temporary = `${filename}.${process.pid}.tmp`
      await writeFile(temporary, content, { flag: 'wx' })
      await rename(temporary, filename)
    }
  }

  if (bundle) {
    const destination = path.resolve(bundle)
    await mkdir(destination)
    const runtime = ['index.html', 'exhibit.css', 'main.js', 'renderer.js', 'hall-hanging.js', 'vendor/three-gallery.js', 'vendor/LICENSE.txt']
    for (const file of [...assets, ...runtime.map(name => path.join(worlds, name))].sort()) {
      const target = path.join(destination, path.relative(publicRoot, file))
      await mkdir(path.dirname(target), { recursive: true })
      await copyFile(file, target)
    }
    for (const [file, content] of outputs) await writeFile(path.join(destination, path.relative(publicRoot, file)), content)
    console.log(`Bundle: ${destination}`)
  }
  console.log(`${registry.length} works, ${registry.length - pending.length} finished rooms${pending.length ? '. Pending: ' + pending.join(', ') : ''}`)
}

assemble().catch(error => { console.error(error.message); process.exitCode = 1 })
